const fs = require('fs');

const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
let inputIndex = 0;

const nextToken = () => input[inputIndex++];
const nextInt = () => parseInt(nextToken(), 10);
const nextLong = () => BigInt(nextToken());

class Node {
    constructor(char, index, n) {
        this.char = char;
        this.index = index;
        this.nextArray = new Array(26).fill(null);
        this.hasCul = false;
        this.isSame = false;
        this.nextCount = 0;
        this.nextList = [];
        this.countArray = new Array(n).fill(0n);
    }

    addNext(index, node) {
        if (this.nextArray[index] === null) {
            this.nextCount++;
            this.nextArray[index] = node;
            this.nextList.push(node);
        }
    }
}

function find(node) {
    if (node.hasCul) {
        return;
    }

    node.countArray[0] += 1n;

    for (const nextNode of node.nextList) {
        find(nextNode);
        for (let i = 0; i < nextNode.countArray.length; i++) {
            const val = nextNode.countArray[i];
            if (val > 0n) {
                if (i + 1 < node.countArray.length) {
                    node.countArray[i + 1] += val;
                }
            }
        }
    }

    node.hasCul = true;
}

function main() {
    const n = nextInt();
    const k = nextLong();
    const str = nextToken();

    const letters = new Array(26).fill(false);
    const list = [];

    for (let i = 0; i < str.length; i++) {
        const char = str[i];
        const node = new Node(char, i, n);
        const charIndex = char.charCodeAt(0) - 97;
        if (letters[charIndex]) {
            node.isSame = true;
        } else {
            letters[charIndex] = true;
        }
        list.push(node);
    }

    for (let i = 0; i < list.length; i++) {
        const ai = list[i];
        for (let j = i + 1; j < list.length; j++) {
            const aj = list[j];
            ai.addNext(aj.char.charCodeAt(0) - 97, aj);
        }
    }

    for (const node of list) {
        find(node);
    }

    const totalCountArray = new Array(n).fill(0n);
    for (let i = 0; i < n; i++) {
        for (const node of list) {
            if (!node.isSame) {
                totalCountArray[i] += node.countArray[i];
            }
        }
    }

    let totalCost = 0n;
    let selectCount = 0n;

    for (let i = n - 1; i >= 0; i--) {
        const available = totalCountArray[i];
        if (selectCount + available < k) {
            totalCost += BigInt(n - 1 - i) * available;
            selectCount += available;
        } else {
            const over = (selectCount + available) - k;
            const take = available - over;
            totalCost += BigInt(n - 1 - i) * take;
            selectCount += take;
            break;
        }
    }

    if (selectCount < k) {
        if (selectCount === k - 1n) {
            console.log((totalCost + BigInt(n)).toString());
        } else {
            console.log(-1);
        }
    } else {
        console.log(totalCost.toString());
    }
}

main();

